import {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { mountSavantExperience } from "./experience";

interface LandingPageProps {
  entered: boolean;
  onReady?: () => void;
}

interface Capability {
  index: string;
  name: string;
  description: string;
  signal: string;
}

const capabilities: Capability[] = [
  {
    index: "01",
    name: "Palaver",
    description:
      "Conversation becomes an operational interface rather than a detached chat surface.",
    signal: "interaction",
  },
  {
    index: "02",
    name: "Envoy",
    description:
      "Persona and cognitive composition remain explicit, modular, and independently addressable.",
    signal: "identity",
  },
  {
    index: "03",
    name: "Opus",
    description:
      "Model execution is separated from conversation, authority, memory, and mutation.",
    signal: "execution",
  },
  {
    index: "04",
    name: "Coda",
    description:
      "Durable mutation is bounded as its own capability instead of being hidden inside reasoning.",
    signal: "mutation",
  },
  {
    index: "05",
    name: "Niche",
    description:
      "Work is governed as finite, explicit, stateful tasks rather than ephemeral intention.",
    signal: "governance",
  },
  {
    index: "06",
    name: "Scrybe",
    description:
      "Context and recall are treated as composable substrates with provenance and replay.",
    signal: "memory",
  },
];

const principles = [
  ["Authority", "Meaning has precedence. Implementation follows authority, never the reverse."],
  ["Composition", "Atomic substance is instantiated once and reused through explicit composition."],
  ["Projection", "Derived structures emerge deterministically instead of becoming duplicate truth."],
  ["Lineage", "Identity, provenance, dependencies, and dependents remain visible and recoverable."],
  ["Optionality", "Systems evolve by extension and reversible migration rather than destructive replacement."],
  ["Determinism", "The same authoritative primitives should produce the same derived state."],
];

const architecture = [
  "conversation",
  "persona",
  "execution",
  "mutation",
  "governance",
  "memory",
  "substantiation",
  "presentation",
  "authority",
  "normalization",
  "assurance",
  "evolution",
  "derivation",
  "mechanics",
  "evidence",
  "knowledge",
  "projection",
  "identity",
  "composition",
];

export function LandingPage({
  entered,
  onReady,
}: LandingPageProps) {
  const root = useRef<HTMLElement>(null);
  const [commandOpen, setCommandOpen] = useState(false);
  const [localTime, setLocalTime] = useState("");
  const architectureString = useMemo(
    () => architecture.join(" · "),
    [],
  );

  useLayoutEffect(() => {
    onReady?.();
  }, [onReady]);

  useEffect(() => {
    return mountSavantExperience({
      root,
      entered,
    });
  }, [entered]);

  useEffect(() => {
    const update = () =>
      setLocalTime(
        new Intl.DateTimeFormat(undefined, {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        }).format(new Date()),
      );

    update();
    const timer = window.setInterval(update, 1000);

    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    const keydown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setCommandOpen((value) => !value);
      }

      if (event.key === "Escape") {
        setCommandOpen(false);
      }
    };

    window.addEventListener("keydown", keydown);

    return () => window.removeEventListener("keydown", keydown);
  }, []);

  const jump = (id: string) => {
    setCommandOpen(false);
    document.getElementById(id)?.scrollIntoView({
      behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth",
    });
  };

  return (
    <main
      ref={root}
      id="site-main"
      className={`site ${entered ? "site--entered" : ""}`}
      tabIndex={-1}
      aria-hidden={!entered}
      data-active-section="home"
    >
      <div className="site__ambient" aria-hidden="true">
        <div className="site__cursor-light" />
        <div className="site__grid" />
        <div className="site__noise" />
      </div>

      <div className="site__progress" aria-hidden="true">
        <span />
      </div>

      <nav className="site__nav" aria-label="Primary">
        <a className="brand" href="#home" data-magnetic>
          <span className="brand__mark">S</span>
          <span className="brand__word">SAVANT</span>
        </a>

        <div className="site__nav-links">
          <a href="#system">System</a>
          <a href="#principles">Principles</a>
          <a href="#architecture">Architecture</a>
          <a href="#contact">Contact</a>
        </div>

        <button
          type="button"
          className="command-trigger"
          data-magnetic
          onClick={() => setCommandOpen(true)}
          aria-expanded={commandOpen}
        >
          <span>Command</span>
          <kbd>⌘K</kbd>
        </button>
      </nav>

      <section
        id="home"
        className="site__hero"
        data-section="home"
      >
        <div className="hero__signal" data-parallax="6" aria-hidden="true">
          <span />
          <span />
          <span />
        </div>

        <div className="hero__meta" data-reveal>
          <span>Self-hosted intelligence architecture</span>
          <span className="hero__meta-status">
            <i />
            system active
          </span>
        </div>

        <div className="hero__title-wrap">
          <p className="eyebrow" data-reveal>
            intelligence / composition / emergence
          </p>

          <h1 data-reveal>
            <span>SAVANT</span>
          </h1>

          <div className="hero__thesis" data-reveal>
            <p>
              Intelligence is not a feature.
            </p>
            <p>
              It is a system of explicit authority, reusable substance,
              deterministic projection, and controlled evolution.
            </p>
          </div>
        </div>

        <div className="hero__footer" data-reveal>
          <button
            type="button"
            className="site__cta"
            data-magnetic
            onClick={() => jump("system")}
          >
            <span>Enter the architecture</span>
            <span aria-hidden="true">↘</span>
          </button>

          <div className="hero__coordinates">
            <span>runtime / active</span>
            <span>{localTime || "—"}</span>
          </div>
        </div>

        <div className="hero__orbital" aria-hidden="true">
          <div className="hero__orbital-ring hero__orbital-ring--one" />
          <div className="hero__orbital-ring hero__orbital-ring--two" />
          <div className="hero__orbital-core" />
        </div>
      </section>

      <section
        id="system"
        className="site__section system-section"
        data-section="system"
      >
        <header className="section-heading">
          <p className="eyebrow" data-reveal>
            01 / substantiated system
          </p>

          <h2 data-reveal>
            Not an assistant.
            <br />
            <em>An architecture.</em>
          </h2>

          <p className="section-heading__lede" data-reveal>
            Savant decomposes intelligence into bounded capabilities so
            conversation, identity, execution, memory, mutation, authority,
            and presentation do not collapse into one opaque machine.
          </p>
        </header>

        <div className="capability-grid">
          {capabilities.map((capability) => (
            <article
              key={capability.name}
              className="capability-card"
              data-depth
              data-reveal
            >
              <div className="capability-card__top">
                <span>{capability.index}</span>
                <span className="capability-card__signal">
                  {capability.signal}
                </span>
              </div>

              <h3>{capability.name}</h3>
              <p>{capability.description}</p>

              <div className="capability-card__trace" data-trace />
            </article>
          ))}
        </div>
      </section>

      <section
        id="principles"
        className="site__section principles-section"
        data-section="principles"
      >
        <div className="principles-intro">
          <p className="eyebrow" data-reveal>
            02 / governing logic
          </p>

          <h2 data-reveal>
            Substance once.
            <br />
            Meaning preserved.
            <br />
            Structure emerges.
          </h2>
        </div>

        <div className="principles-list">
          {principles.map(([name, description], index) => (
            <article
              key={name}
              className="principle"
              data-reveal
            >
              <span className="principle__index">
                {String(index + 1).padStart(2, "0")}
              </span>
              <h3>{name}</h3>
              <p>{description}</p>
              <span className="principle__arrow" aria-hidden="true">
                ↗
              </span>
            </article>
          ))}
        </div>
      </section>

      <section
        id="architecture"
        className="site__section architecture-section"
        data-section="architecture"
      >
        <div className="architecture-stage">
          <p className="eyebrow" data-reveal>
            03 / modular hierarchy
          </p>

          <h2 data-reveal>
            Components do not merely connect.
            <br />
            They substantiate one another.
          </h2>

          <div className="architecture-field" data-reveal>
            <div className="architecture-field__core">
              <span>SAVANT</span>
              <small>runtime</small>
            </div>

            {architecture.slice(0, 12).map((item, index) => (
              <span
                key={item}
                className="architecture-node"
                style={
                  {
                    "--node-index": index,
                  } as React.CSSProperties
                }
              >
                {item}
              </span>
            ))}

            <div
              className="architecture-field__orbit architecture-field__orbit--a"
              aria-hidden="true"
            />
            <div
              className="architecture-field__orbit architecture-field__orbit--b"
              aria-hidden="true"
            />
          </div>
        </div>

        <div className="architecture-marquee" aria-label={architectureString}>
          <div>
            <span>{architectureString}</span>
            <span aria-hidden="true">{architectureString}</span>
          </div>
        </div>
      </section>

      <section
        className="site__section authority-section"
        data-section="authority"
      >
        <div className="authority-copy">
          <p className="eyebrow" data-reveal>
            04 / authority before inference
          </p>

          <h2 data-reveal>
            The system knows the difference between what is true,
            what is derived, and what is merely possible.
          </h2>
        </div>

        <div className="authority-stack">
          {[
            "current directive",
            "authoritative graph",
            "accepted decisions",
            "constitutional canon",
            "verified implementation",
            "admitted evidence",
            "deterministic projection",
          ].map((item, index) => (
            <div
              className="authority-row"
              key={item}
              data-reveal
            >
              <span>{String(index + 1).padStart(2, "0")}</span>
              <strong>{item}</strong>
              <i />
            </div>
          ))}
        </div>
      </section>

      <section
        className="site__section manifesto-section"
        data-section="manifesto"
      >
        <div className="manifesto__number" data-parallax="16">
          01
        </div>

        <div className="manifesto__copy">
          <p className="eyebrow" data-reveal>
            the proposition
          </p>

          <blockquote data-reveal>
            A system becomes more intelligent when its parts can remain
            themselves while becoming something larger.
          </blockquote>

          <p data-reveal>
            Savant is built around that premise: preserve identity,
            preserve authority, preserve history, and let higher-order
            structures emerge through composition rather than duplication.
          </p>
        </div>
      </section>

      <footer
        id="contact"
        className="site__footer"
        data-section="contact"
      >
        <div className="footer__statement" data-reveal>
          <p className="eyebrow">Savant / system online</p>
          <h2>
            Intelligence,
            <br />
            given form.
          </h2>
        </div>

        <div className="footer__meta" data-reveal>
          <div>
            <span>Repository</span>
            <a
              href="https://github.com/savant-git/savant-runtime"
              target="_blank"
              rel="noreferrer"
            >
              savant-runtime ↗
            </a>
          </div>

          <div>
            <span>Interface</span>
            <a href="#home">return to signal ↑</a>
          </div>
        </div>

        <div className="footer__wordmark" aria-hidden="true">
          SAVANT
        </div>
      </footer>

      {commandOpen && (
        <div
          className="command-layer"
          role="dialog"
          aria-modal="true"
          aria-label="Savant command palette"
          onMouseDown={(event) => {
            if (event.currentTarget === event.target) {
              setCommandOpen(false);
            }
          }}
        >
          <div className="command-palette">
            <header>
              <span>SAVANT / NAVIGATE</span>
              <kbd>ESC</kbd>
            </header>

            {[
              ["home", "Return to signal"],
              ["system", "Explore system"],
              ["principles", "Read governing logic"],
              ["architecture", "View architecture"],
              ["contact", "Repository and contact"],
            ].map(([id, label], index) => (
              <button
                type="button"
                key={id}
                onClick={() => jump(id)}
              >
                <span>{String(index + 1).padStart(2, "0")}</span>
                <strong>{label}</strong>
                <i>↘</i>
              </button>
            ))}
          </div>
        </div>
      )}
    </main>
  );
}
