import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import type { RefObject } from "react";

gsap.registerPlugin(ScrollTrigger);

interface SavantExperienceOptions {
  root: RefObject<HTMLElement | null>;
  entered: boolean;
}

const supportsFinePointer = () =>
  window.matchMedia("(pointer: fine)").matches &&
  !window.matchMedia("(prefers-reduced-motion: reduce)").matches;

export function mountSavantExperience({
  root,
  entered,
}: SavantExperienceOptions): () => void {
  const element = root.current;

  if (!element || !entered) return () => undefined;

  const reducedMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  const cleanups: Array<() => void> = [];

  element.dataset.motion = reducedMotion ? "reduced" : "full";

  const context = gsap.context(() => {
    const revealElements = gsap.utils.toArray<HTMLElement>(
      "[data-reveal]",
      element,
    );

    if (reducedMotion) {
      gsap.set(revealElements, {
        opacity: 1,
        y: 0,
        filter: "blur(0px)",
      });
    } else {
      revealElements.forEach((target) => {
        gsap.fromTo(
          target,
          {
            opacity: 0,
            y: 44,
            filter: "blur(9px)",
          },
          {
            opacity: 1,
            y: 0,
            filter: "blur(0px)",
            duration: 1.15,
            ease: "power4.out",
            scrollTrigger: {
              trigger: target,
              start: "top 88%",
              once: true,
            },
          },
        );
      });

      gsap.utils
        .toArray<HTMLElement>("[data-parallax]", element)
        .forEach((target) => {
          const strength = Number(target.dataset.parallax ?? "7");

          gsap.fromTo(
            target,
            { yPercent: strength * -0.5 },
            {
              yPercent: strength * 0.5,
              ease: "none",
              scrollTrigger: {
                trigger: target.closest("section") ?? target,
                start: "top bottom",
                end: "bottom top",
                scrub: 1.2,
              },
            },
          );
        });

      gsap.utils
        .toArray<HTMLElement>("[data-trace]", element)
        .forEach((target) => {
          gsap.fromTo(
            target,
            { scaleX: 0 },
            {
              scaleX: 1,
              ease: "none",
              scrollTrigger: {
                trigger: target,
                start: "top 90%",
                end: "top 35%",
                scrub: 0.8,
              },
            },
          );
        });
    }
  }, element);

  cleanups.push(() => context.revert());

  const updateScroll = () => {
    const max =
      document.documentElement.scrollHeight -
      document.documentElement.clientHeight;

    const progress =
      max > 0 ? Math.min(1, Math.max(0, window.scrollY / max)) : 0;

    element.style.setProperty("--scroll-progress", String(progress));
    element.style.setProperty(
      "--scroll-progress-percent",
      `${progress * 100}%`,
    );
  };

  updateScroll();
  window.addEventListener("scroll", updateScroll, { passive: true });
  window.addEventListener("resize", updateScroll, { passive: true });

  cleanups.push(() => {
    window.removeEventListener("scroll", updateScroll);
    window.removeEventListener("resize", updateScroll);
  });

  if (supportsFinePointer()) {
    const pointer = {
      x: window.innerWidth / 2,
      y: window.innerHeight / 2,
    };

    const rendered = {
      x: pointer.x,
      y: pointer.y,
    };

    let frame = 0;

    const render = () => {
      rendered.x += (pointer.x - rendered.x) * 0.11;
      rendered.y += (pointer.y - rendered.y) * 0.11;

      element.style.setProperty("--pointer-x", `${rendered.x}px`);
      element.style.setProperty("--pointer-y", `${rendered.y}px`);
      element.style.setProperty(
        "--pointer-x-normalized",
        String(rendered.x / Math.max(1, window.innerWidth) - 0.5),
      );
      element.style.setProperty(
        "--pointer-y-normalized",
        String(rendered.y / Math.max(1, window.innerHeight) - 0.5),
      );

      frame = window.requestAnimationFrame(render);
    };

    const move = (event: PointerEvent) => {
      pointer.x = event.clientX;
      pointer.y = event.clientY;
    };

    window.addEventListener("pointermove", move, { passive: true });
    frame = window.requestAnimationFrame(render);

    cleanups.push(() => {
      window.removeEventListener("pointermove", move);
      window.cancelAnimationFrame(frame);
    });

    const magnetic = Array.from(
      element.querySelectorAll<HTMLElement>("[data-magnetic]"),
    );

    magnetic.forEach((target) => {
      const handleMove = (event: PointerEvent) => {
        const rect = target.getBoundingClientRect();
        const x = event.clientX - rect.left - rect.width / 2;
        const y = event.clientY - rect.top - rect.height / 2;

        gsap.to(target, {
          x: x * 0.16,
          y: y * 0.16,
          duration: 0.45,
          ease: "power3.out",
        });
      };

      const reset = () => {
        gsap.to(target, {
          x: 0,
          y: 0,
          duration: 0.7,
          ease: "elastic.out(1, 0.45)",
        });
      };

      target.addEventListener("pointermove", handleMove);
      target.addEventListener("pointerleave", reset);

      cleanups.push(() => {
        target.removeEventListener("pointermove", handleMove);
        target.removeEventListener("pointerleave", reset);
      });
    });
  }

  const sections = Array.from(
    element.querySelectorAll<HTMLElement>("[data-section]"),
  );

  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((entry) => entry.isIntersecting)
          .sort(
            (a, b) =>
              b.intersectionRatio - a.intersectionRatio,
          )[0];

        if (!visible) return;

        const id = (visible.target as HTMLElement).dataset.section;

        if (id) {
          element.dataset.activeSection = id;
        }
      },
      {
        threshold: [0.2, 0.45, 0.7],
      },
    );

    sections.forEach((section) => observer.observe(section));
    cleanups.push(() => observer.disconnect());
  }

  const cards = Array.from(
    element.querySelectorAll<HTMLElement>("[data-depth]"),
  );

  if (supportsFinePointer()) {
    cards.forEach((card) => {
      const move = (event: PointerEvent) => {
        const rect = card.getBoundingClientRect();
        const px = (event.clientX - rect.left) / rect.width - 0.5;
        const py = (event.clientY - rect.top) / rect.height - 0.5;

        card.style.setProperty("--depth-x", String(px));
        card.style.setProperty("--depth-y", String(py));
      };

      const leave = () => {
        card.style.setProperty("--depth-x", "0");
        card.style.setProperty("--depth-y", "0");
      };

      card.addEventListener("pointermove", move);
      card.addEventListener("pointerleave", leave);

      cleanups.push(() => {
        card.removeEventListener("pointermove", move);
        card.removeEventListener("pointerleave", leave);
      });
    });
  }

  return () => {
    cleanups.reverse().forEach((cleanup) => cleanup());
    ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
  };
}
